<?php
/**
 * CSRF (Cross-Site Request Forgery) protection helpers.
 *
 * Malcolm Lismore Photography
 *
 * Any form that changes state (enquiry submission, login, admin actions)
 * should include a token generated by csrf_token() and verify it with
 * csrf_verify() before doing anything with the submitted data.
 */

declare(strict_types=1);

/**
 * Ensure a session is running and return the current CSRF token,
 * generating one on first use.
 */
function csrf_token(): string
{
    if (session_status() === PHP_SESSION_NONE) {
        session_start();
    }
    if (empty($_SESSION['csrf_token'])) {
        $_SESSION['csrf_token'] = bin2hex(random_bytes(32));
    }
    return $_SESSION['csrf_token'];
}

/**
 * Output a ready-made hidden input field containing the CSRF token.
 */
function csrf_field(): string
{
    return '<input type="hidden" name="csrf_token" value="' . e(csrf_token()) . '">';
}

/**
 * Verify that the submitted CSRF token matches the session token.
 * Uses hash_equals() to prevent timing attacks.
 */
function csrf_verify(?string $token): bool
{
    if (session_status() === PHP_SESSION_NONE) {
        session_start();
    }
    if (empty($_SESSION['csrf_token']) || !is_string($token)) {
        return false;
    }
    return hash_equals($_SESSION['csrf_token'], $token);
}

/**
 * Convenience method: verify the token from $_POST, or abort with 419.
 */
function csrf_check_or_abort(): void
{
    if ($_SERVER['REQUEST_METHOD'] === 'POST') {
        if (!csrf_verify($_POST['csrf_token'] ?? null)) {
            http_response_code(419);
            exit('Your session has expired or the security token was invalid. Please go back and try again.');
        }
    }
}
